sp_widget.css:
.sp-hero {
  background: linear-gradient(135deg, lighten($brand-primary, 30%) 0%, lighten($brand-primary, 15%) 50%, $brand-primary 100%);
  border-radius: $border-radius-large;
  overflow: hidden;
  position: relative;
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    background: rgba($btn-primary-color, 0.15);
    pointer-events: none;
  }
}
.sp-hero-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 48px 48px;
  position: relative;
  z-index: 1;
  flex-wrap: wrap;
  gap: 16px;
}
.sp-hero-title {
  font-size: 32px;
  font-weight: 700;
  color: $btn-primary-color;
  margin: 0 0 8px;
  line-height: 1.2;
}
.sp-hero-subtitle {
  font-size: $font-size-base;
  color: $btn-primary-color;
  opacity: 0.85;
  margin: 0;
  max-width: 560px;
}
.sp-hero-btn {
  background: rgba($btn-primary-color, 0.85);
  color: $brand-primary;
  border: none;
  border-radius: $border-radius-base;
  height: 44px;
  padding: 0 20px;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  backdrop-filter: blur(4px);
  transition: background 0.15s;
  &:hover {
    background: $btn-primary-color;
  }
}

sp_widget.script:
(function() {
  data.firstName = '';
  data.greeting = '';

  try {
    var userId = gs.getUserID();
    var userGr = new GlideRecord('sys_user');
    userGr.setLimit(1);
    if (userGr.get(userId)) {
      data.firstName = userGr.getValue('first_name') + '';
    }
    if (!data.firstName) {
      data.firstName = 'User';
    }
    data.greeting = 'Hi ' + data.firstName + ', Welcome to Flash';
  } catch (e) {
    gs.error('bf_welcome widget error: ' + e.message);
    data.firstName = 'User';
    data.greeting = 'Hi User, Welcome to Flash';
  }
})();
